/**
 * context/PortfolioContext.jsx
 * Global state: danh sách portfolios, portfolio đang chọn, credentials.
 */
import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
import { getPortfolios } from '../api/client';

const PortfolioContext = createContext(null);

export function PortfolioProvider({ children }) {
  const [portfolios, setPortfolios] = useState([]);
  const [activePortfolioId, setActivePortfolioId] = useState(null);
  const [isAuthenticated, setIsAuthenticated] = useState(
    () => !!localStorage.getItem('vninvest_creds')
  );
  const [loading, setLoading] = useState(false);

  const login = useCallback((username, password) => {
    const encoded = btoa(`${username}:${password}`);
    localStorage.setItem('vninvest_creds', encoded);
    setIsAuthenticated(true);
  }, []);

  const logout = useCallback(() => {
    localStorage.removeItem('vninvest_creds');
    setIsAuthenticated(false);
    setPortfolios([]);
    setActivePortfolioId(null);
  }, []);

  const fetchPortfolios = useCallback(async () => {
    setLoading(true);
    try {
      const res = await getPortfolios();
      setPortfolios(res.data);
      if (res.data.length > 0 && !activePortfolioId) {
        setActivePortfolioId(res.data[0].id);
      }
    } catch {
      // lỗi 401 được xử lý bởi interceptor
    } finally {
      setLoading(false);
    }
  }, [activePortfolioId]);

  useEffect(() => {
    if (isAuthenticated) {
      fetchPortfolios();
    }
  }, [isAuthenticated]); // eslint-disable-line

  return (
    <PortfolioContext.Provider value={{
      portfolios,
      activePortfolioId,
      setActivePortfolioId,
      isAuthenticated,
      login,
      logout,
      loading,
      fetchPortfolios,
    }}>
      {children}
    </PortfolioContext.Provider>
  );
}

export function usePortfolio() {
  const ctx = useContext(PortfolioContext);
  if (!ctx) throw new Error('usePortfolio must be used inside PortfolioProvider');
  return ctx;
}
